from pathlib import Path
import json,html,re
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def m(tex,display=True):
 tag='div'if display else'span';return f'<{tag} class="math" data-display="{str(display).lower()}" data-tex="{html.escape(tex,quote=True)}"></{tag}>'
def refs(items):return '<div class="proof-links">'+''.join(f'<a href="{u}">{l} ↗</a>'for u,l in items)+'</div>'
def main():
 assert json.loads((HERE/'verification.json').read_text())['passed'];assert json.loads((HERE/'independent-verification.json').read_text())['passed']
 css=re.search(r'<style>(.*?)</style>',(ROOT/'research/t2-qec-upper/index.html').read_text(),re.S).group(1)+'\n.math{max-width:100%;overflow-x:auto}.scroll{overflow-x:auto}'
 b='<p class="eyebrow">Anticoherent subspaces · General analytical upper bound</p><a href="../../index.html">← Catalogue</a><h1>A cubic bound from auxiliary spin five-halves</h1>'
 b+='<div class="result">'+m(r'\boxed{6K(N,t)\le N-4\qquad(N\ge19,\ t\ge3).}')+'<p>This bounds the third-order subspace dimension by two at both nineteen and twenty qubits. The proof covers arbitrary complex subspaces.</p></div>'
 b+='<section><h2>Zero compression from third-order anticoherence</h2><p>Write '+m(r'j=N/2',False)+' and couple physical spin '+m(r'j',False)+' to an auxiliary spin '+m(r'5/2',False)+':</p>'+m(r'X=\mathbf J\cdot\mathbf S,\qquad F_j(X)=-(2X+3j+8)(2X-3j+5)(2X-5j),')+m(r'c_j=\frac{20}{3}j(j-9)(2j-1),\qquad W=F_j(X)-c_jI.')+'<p>The normalized trace of the cubic is '+m(r'c_j',False)+'. Rotation invariance makes its physical partial trace scalar, so '+m(r'\operatorname{Tr}_{V_j}W=0',False)+'. For an AC3 subspace with projector '+m(r'P',False)+', every physical-spin polynomial of degree at most three compresses to its normalized trace. Consequently</p>'+m(r'(P\otimes I_6)W(P\otimes I_6)=0.')+'</section>'
 b+='<section><h2>The exact spectral sign pattern</h2><p>The six total-spin sectors are '+m(r'L=j-5/2+p',False)+', for '+m(r'p=0,\ldots,5',False)+'. The values of the uncentered cubic are:</p><div class="scroll"><table><thead><tr><th>'+m(r'p',False)+'</th><th>'+m(r'F_j(x_L)',False)+'</th></tr></thead><tbody>'
 for p,v in enumerate([r'40j(2j-3)(2j+1)',r'0',r'-12(j+1)(2j-1)(2j+3)',r'-16j(j+2)(2j+3)',r'0',r'0']):b+='<tr><td>'+str(p)+'</td><td>'+m(v,False)+'</td></tr>'
 b+='</tbody></table></div><p>For '+m(r'j\ge19/2',False)+', the centering constant is strictly positive. All sectors except the lowest become strictly negative; trace zero forces the remaining sector positive. Thus</p>'+m(r'n_+(W)=N-4,\qquad n_-(W)=5(N+2),\qquad n_0(W)=0.')+'<p>The space '+m(r'\mathcal C\otimes V_{5/2}',False)+' has dimension '+m(r'6k',False)+' and zero compression. Projection into the positive spectral space is injective, because a nonzero vector with no positive component would have negative quadratic form. Hence '+m(r'6k\le N-4',False)+'.</p></section>'
 b+='<section><h2>Nineteen and twenty qubits</h2>'+m(r'6K(19,3)\le15,\qquad6K(20,3)\le16.')+'<p>Both maxima are at most two. The linked analytical planes provide exact lower bounds and make these upper bounds sharp.</p>'+refs([('../n19-t3/index.html','Nineteen-qubit analytical plane'),('../n20-t3/index.html','Twenty-qubit analytical plane')])+'</section>'
 b+='<section><h2>Exact verification</h2><p>Independent physical-spin implementations reconstruct all magnetic blocks, check characteristic polynomials and physical partial traces exactly at both sizes, and verify the general polynomial trace identity. Numerical eigenvalues are not used.</p>'+refs([('proof.tex','Complete analytical proof'),('verify.py','Exact integral-basis verifier'),('verification.json','Verification report'),('verify_independently.py','Independent normalized-spin verifier'),('independent-verification.json','Independent report')])+'</section>'
 head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A general third-order AC-subspace bound</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-tex]").forEach(el=>{if(window.katex)el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==="true",throwOnError:false,strict:"ignore",trust:false});}));</script></head><body><main>'
 (HERE/'index.html').write_text(head+b+'</main></body></html>\n')
if __name__=='__main__':main()
